// PV-Leistung aus der shelly-monitor API lesen
const pv = msg.payload && msg.payload.current && msg.payload.current.pv;
if (pv == null) {
    node.warn('Keine PV-Daten in der API-Antwort');
    return null;
}
const watts = Math.round(pv);

// Portal-ID des Cerbo GX (Einstellungen → VRM Online Portal)
const portalId = env.get('VICTRON_PORTAL_ID') || 'EURE_PORTAL_ID_HIER';
const instance = 'shelly_30';
const base     = `W/${portalId}/com.victronenergy.pvinverter.${instance}`;

// Mehrere dbus-Pfade aktualisieren
const msgs = [
    { topic: `${base}/Ac/Power`,      payload: JSON.stringify({ value: watts }) },
    { topic: `${base}/Ac/L1/Power`,   payload: JSON.stringify({ value: watts }) },
    { topic: `${base}/Ac/L1/Voltage`, payload: JSON.stringify({ value: 230 }) },
    { topic: `${base}/Ac/L1/Current`, payload: JSON.stringify({ value: +(watts / 230).toFixed(2) }) },
    { topic: `${base}/StatusCode`,    payload: JSON.stringify({ value: 7 }) },
    { topic: `${base}/Connected`,     payload: JSON.stringify({ value: 1 }) },
];

// Status-Anzeige im Node
node.status({ fill: 'green', shape: 'dot', text: `${watts} W` });

return [msgs, { payload: watts }];
